use stable_mla_gemm::Span;
use stable_mla_ops::{Codec,Gather,Ops};
use cudarc::driver::{sys,CudaDevice,CudaSlice};
use serde::Deserialize;use serde_json::json;use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},sync::Arc};
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Identity{path:PathBuf,bytes:usize,sha256:String}
fn hash(v:&[u8])->String{format!("{:x}",Sha256::digest(v))}
impl Identity{fn read(&self)->Result<Vec<u8>,String>{let v=fs::read(&self.path).map_err(|e|e.to_string())?;if v.len()!=self.bytes||hash(&v)!=self.sha256{return Err(format!("identity mismatch {}",self.path.display()))}Ok(v)}}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]struct Plan{gpu_uuid:String,ptx:Identity,provenance:Identity,rows:usize,heads:usize,ccd:usize,rope:usize,nope:usize,context:usize,slots:usize,codec:usize,partitions:Vec<usize>,query:Identity,absorb:Identity,ckv:Identity,kpe:Identity,positions:Identity,selected:Identity,bf16:Identity}
fn f32s(v:&[u8])->Result<Vec<f32>,String>{if v.len()%4!=0{return Err("F32 byte extent".into())}Ok(v.chunks_exact(4).map(|x|f32::from_le_bytes(x.try_into().unwrap())).collect())}
fn i32s(v:&[u8])->Result<Vec<i32>,String>{if v.len()%4!=0{return Err("I32 byte extent".into())}Ok(v.chunks_exact(4).map(|x|i32::from_le_bytes(x.try_into().unwrap())).collect())}
fn serial(v:&[f32])->Vec<u8>{v.iter().flat_map(|x|x.to_le_bytes()).collect()}
fn check(a:&[f32],b:&[f32],label:&str)->Result<(),String>{if serial(a)!=serial(b){return Err(format!("{label}: complete F32 bytes differ (lengths {} {})",a.len(),b.len()))}Ok(())}
fn bf(v:f32)->u16{let bits=v.to_bits();((bits.wrapping_add(0x7fff+((bits>>16)&1)))>>16)as u16}
fn cache(v:&[u8],pos:usize,width:usize,dim:usize,k6:bool)->f32{let bytes=if k6{14}else{10};let at=(pos*(width/16)+dim/16)*bytes;let scale=f32::from_bits((u16::from_le_bytes([v[at],v[at+1]])as u32)<<16);let j=dim%16;let code=if k6{let bit=j*6;let byte=bit/8;let lo=v[at+2+byte]as u32;let hi=if byte+1<12{(v[at+3+byte]as u32)<<8}else{0};((lo|hi)>>(bit%8))&63}else{((v[at+2+j/2]>>((j%2)*4))&15)as u32};scale*(code as i32-if k6{32}else{8})as f32}
fn copy<T:cudarc::driver::DeviceRepr+Clone>(d:&Arc<CudaDevice>,v:&[T])->Result<CudaSlice<T>,String>{d.htod_sync_copy(v).map_err(|e|e.to_string())}
fn read(d:&Arc<CudaDevice>,v:&CudaSlice<f32>)->Result<Vec<f32>,String>{d.synchronize().map_err(|e|e.to_string())?;d.dtoh_sync_copy(v).map_err(|e|e.to_string())}
fn reset32(d:&Arc<CudaDevice>,v:&CudaSlice<f32>,bits:u32)->Result<(),String>{use cudarc::driver::{DevicePtr,DeviceSlice};unsafe{sys::lib().cuMemsetD32Async(*v.device_ptr(),bits,v.len(),*d.cu_stream())}.result().map_err(|e|e.to_string())}
fn reset16(d:&Arc<CudaDevice>,v:&CudaSlice<u16>,bits:u16)->Result<(),String>{use cudarc::driver::{DevicePtr,DeviceSlice};unsafe{sys::lib().cuMemsetD16Async(*v.device_ptr(),bits,v.len(),*d.cu_stream())}.result().map_err(|e|e.to_string())}
fn run(plan:&Path,root:&Path)->Result<(),String>{
 let plan_raw=fs::read(plan).map_err(|e|e.to_string())?;let p:Plan=serde_json::from_slice(&plan_raw).map_err(|e|e.to_string())?;
 if root.exists(){return Err("fresh output required".into())}p.provenance.read()?;let d=CudaDevice::new_with_stream(0).map_err(|e|e.to_string())?;
 let mut uuid=unsafe{std::mem::zeroed::<sys::CUuuid>()};unsafe{sys::lib().cuDeviceGetUuid_v2(&mut uuid,*d.cu_device())}.result().map_err(|e|e.to_string())?;let hex=uuid.bytes.iter().map(|b|format!("{:02x}",*b as u8)).collect::<String>();let actual=format!("GPU-{}-{}-{}-{}-{}",&hex[..8],&hex[8..12],&hex[12..16],&hex[16..20],&hex[20..]);if actual!=p.gpu_uuid{return Err("actual GPU identity mismatch".into())}
 let guard=usize::try_from(d.attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_WARP_SIZE).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;
 let ptx=String::from_utf8(p.ptx.read()?).map_err(|e|e.to_string())?;let ops=Ops::load(d.clone(),&ptx)?;let stream=*d.cu_stream();
 let q=f32s(&p.query.read()?)?;let abs=f32s(&p.absorb.read()?)?;let c=p.ckv.read()?;let k=p.kpe.read()?;let positions=i32s(&p.positions.read()?)?;let selected=i32s(&p.selected.read()?)?;
 if positions.len()!=p.rows||selected.len()!=p.rows*p.slots||p.partitions.iter().sum::<usize>()!=p.rows{return Err("row/partition identity".into())}
 let param=Gather{row_start:0,rows:p.rows,heads:p.heads,ccd:p.ccd,rope:p.rope,slots:p.slots,context:p.context,q_abs_row_stride:p.heads*p.ccd,q_abs_head_stride:p.ccd,q_rope_row_stride:p.heads*(p.nope+p.rope),q_rope_head_stride:p.nope+p.rope,codec:match p.codec{4=>Codec::K4,6=>Codec::K6,_=>return Err("codec".into())}};param.validate()?;
 let active=param.outputs()?;let width=p.ccd+p.rope;
 if abs.len()!=p.rows*p.heads*p.ccd||q.len()!=p.rows*p.heads*(p.nope+p.rope)||c.len()!=p.context*(p.ccd/16)*if p.codec==6{14}else{10}||k.len()!=p.context*(p.rope/16)*if p.codec==6{14}else{10}{return Err("qualified input physical extents differ".into())}
 let peak=abs.len()*8+q.len()*4+c.len()+k.len()+selected.len()*4+positions.len()*4+active.iter().sum::<usize>()*4+active[2]*8+p.bf16.bytes*3+(p.heads*(p.rows+1)*p.ccd)*4+p.rows*p.heads*p.ccd*2+guard*4*16;
 let free=cudarc::driver::result::mem_get_info().map_err(|e|e.to_string())?.0;if free<peak.checked_add(600*1024*1024).ok_or("fixture memory extent overflow")?{return Err("measured free VRAM cannot cover actual operator buffers plus default margin".into())}
 let mut oracle=[vec![0f32;active[0]],vec![0f32;active[1]],vec![0f32;active[2]]];
 for r in 0..p.rows{for s in 0..p.slots{let pos=selected[r*p.slots+s];let valid=pos>=0&&pos<(positions[r]as i64+1).clamp(0,p.context as i64)as i32;for dim in 0..width{oracle[0][(r*p.slots+s)*width+dim]=if !valid{0.0}else if dim<p.ccd{cache(&c,pos as usize,p.ccd,dim,p.codec==6)}else{cache(&k,pos as usize,p.rope,dim-p.ccd,p.codec==6)}}for h in 0..p.heads{oracle[2][(r*p.heads+h)*p.slots+s]=if valid{0.0}else{f32::NEG_INFINITY}}}for h in 0..p.heads{for dim in 0..width{oracle[1][(r*p.heads+h)*width+dim]=if dim<p.ccd{abs[(r*p.heads+h)*p.ccd+dim]}else{q[(r*p.heads+h)*(p.nope+p.rope)+p.nope+dim-p.ccd]}}}}
 let da=copy(&d,&abs)?;let dq=copy(&d,&q)?;let dc=copy(&d,&c)?;let dk=if k.is_empty(){None}else{Some(copy(&d,&k)?)};let di=copy(&d,&selected)?;let dp=copy(&d,&positions)?;
 let av=Span::f32(&da,0,abs.len())?;let qv=if p.rope>0{Some(Span::f32(&dq,p.nope,q.len()-p.nope)?)}else{None};let cv=Span::bytes(&dc,0,c.len())?;let kv=if p.rope>0{Some(Span::bytes(dk.as_ref().ok_or("rotary owner absent")?,0,k.len())?)}else{None};let iv=Span::i32(&di,0,selected.len())?;let pv=Span::i32(&dp,0,positions.len())?;
 let sentinel=f32::from_bits(0x7fc12345);let outputs=[copy(&d,&vec![sentinel;active[0]+2*guard])?,copy(&d,&vec![sentinel;active[1]+2*guard])?,copy(&d,&vec![sentinel;active[2]+2*guard])?];
 let launch=|start:usize,rows:usize|->Result<(),String>{let per=[p.slots*width,p.heads*width,p.heads*p.slots];let g=Span::f32(&outputs[0],guard+start*per[0],rows*per[0])?;let q=Span::f32(&outputs[1],guard+start*per[1],rows*per[1])?;let s=Span::f32(&outputs[2],guard+start*per[2],rows*per[2])?;unsafe{ops.gather(Gather{row_start:start,rows,..param},&g,&q,&s,&av,qv.as_ref(),&cv,kv.as_ref(),&iv,&pv,stream)}};
 let validate=||->Result<(),String>{for i in 0..3{let all=read(&d,&outputs[i])?;check(&all[guard..guard+active[i]],&oracle[i],"gather oracle")?;if all[..guard].iter().chain(&all[guard+active[i]..]).any(|x|x.to_bits()!=sentinel.to_bits()){return Err("gather guard overwritten".into())}}Ok(())};
 launch(0,p.rows)?;validate()?;for o in &outputs{reset32(&d,o,sentinel.to_bits())?}let mut start=0;for &rows in &p.partitions{launch(start,rows)?;start+=rows}validate()?;for o in &outputs{reset32(&d,o,sentinel.to_bits())?}for r in 0..p.rows{launch(r,1)?}validate()?;for o in &outputs{reset32(&d,o,sentinel.to_bits())?}
 graph_owner::completed_graph_launch(&d,||launch(0,p.rows))?;validate()?;
 let error=graph_owner::completed_graph_launch(&d,||{launch(0,p.rows)?;Err("injected gather callback failure".into())}).err().ok_or("callback error missing")?;if !error.contains("injected gather"){return Err(error)}validate()?;
 let unwind=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _=graph_owner::completed_graph_launch(&d,||->Result<(),String>{launch(0,p.rows)?;panic!("injected gather callback unwind")});}));if unwind.is_ok(){return Err("unwind missing".into())}graph_owner::completed_graph_launch(&d,||launch(0,p.rows))?;validate()?;
 // Widen actual BF16 operands, then scatter actual widened values with physical head padding.
 let bytes=p.bf16.read()?;if bytes.len()%2!=0||bytes.is_empty(){return Err("BF16 input extent".into())}let bf16:Vec<_>=bytes.chunks_exact(2).map(|x|u16::from_le_bytes(x.try_into().unwrap())).collect();let expected:Vec<_>=bf16.iter().map(|&x|f32::from_bits((x as u32)<<16)).collect();let db=copy(&d,&bf16)?;let dw=copy(&d,&vec![sentinel;bf16.len()+2*guard])?;let bin=Span::bf16(&db,0,bf16.len())?;let wide=Span::f32(&dw,guard,bf16.len())?;
 unsafe{ops.widen(&bin,&wide,bf16.len(),stream)?}check(&read(&d,&dw)?[guard..guard+bf16.len()],&expected,"widen")?;graph_owner::completed_graph_launch(&d,||unsafe{ops.widen(&bin,&wide,bf16.len(),stream)})?;
 let stride=p.rows+1;let count=p.rows*p.heads*p.ccd;let mut padded=vec![sentinel;p.heads*stride*p.ccd];let mut scatter_expected=vec![0u16;count];for r in 0..p.rows{for h in 0..p.heads{for dim in 0..p.ccd{let value=abs[(r*p.heads+h)*p.ccd+dim];padded[(h*stride+r)*p.ccd+dim]=value;scatter_expected[(r*p.heads+h)*p.ccd+dim]=bf(value)}}}let ds=copy(&d,&padded)?;let dout=copy(&d,&vec![0xa55au16;count+2*guard])?;
 let scatter=|start:usize,rows:usize|->Result<(),String>{let input=Span::f32(&ds,start*p.ccd,padded.len()-start*p.ccd)?;let output=Span::bf16(&dout,guard+start*p.heads*p.ccd,rows*p.heads*p.ccd)?;unsafe{ops.scatter(&input,&output,rows,p.heads,p.ccd,stride,stream)}};
 let scatter_check=||->Result<(),String>{d.synchronize().map_err(|e|e.to_string())?;let v=d.dtoh_sync_copy(&dout).map_err(|e|e.to_string())?;if v[guard..guard+count]!=scatter_expected||v[..guard].iter().chain(&v[guard+count..]).any(|&x|x!=0xa55a){return Err("scatter rounded result/guard mismatch".into())}Ok(())};scatter(0,p.rows)?;scatter_check()?;reset16(&d,&dout,0xa55a)?;let mut start=0;for &rows in &p.partitions{scatter(start,rows)?;start+=rows}scatter_check()?;reset16(&d,&dout,0xa55a)?;for r in 0..p.rows{scatter(r,1)?}scatter_check()?;reset16(&d,&dout,0xa55a)?;graph_owner::completed_graph_launch(&d,||scatter(0,p.rows))?;scatter_check()?;
 // Softmax actual gathered dot products with explicit causal/sentinel mask; F64 is mathematical reference.
 let mut scores=oracle[2].clone();let mut reference=vec![0f64;scores.len()];for r in 0..p.rows{for h in 0..p.heads{let offset=(r*p.heads+h)*p.slots;for s in 0..p.slots{if scores[offset+s].is_finite(){let dot:f64=(0..width).map(|dim|oracle[0][(r*p.slots+s)*width+dim]as f64*oracle[1][(r*p.heads+h)*width+dim]as f64).sum();scores[offset+s]=(dot/(width as f64).sqrt())as f32}}let max=scores[offset..offset+p.slots].iter().copied().fold(f32::NEG_INFINITY,f32::max)as f64;let mut total=0.0;for s in 0..p.slots{let value=scores[offset+s];reference[offset+s]=if value.is_finite(){(value as f64-max).exp()}else{0.0};total+=reference[offset+s]}for s in 0..p.slots{reference[offset+s]/=total}}}
 let dscore=copy(&d,&scores)?;let dsoft=copy(&d,&vec![sentinel;scores.len()+2*guard])?;let soft=|start:usize,rows:usize|->Result<(),String>{let offset=start*p.heads*p.slots;let count=rows*p.heads*p.slots;let a=Span::f32(&dscore,offset,count)?;let b=Span::f32(&dsoft,guard+offset,count)?;unsafe{ops.softmax(&a,&b,rows,p.heads,p.slots,stream)}};soft(0,p.rows)?;let baseline=read(&d,&dsoft)?;let mut max_abs=0f64;for (a,b)in baseline[guard..guard+scores.len()].iter().zip(&reference){if !a.is_finite(){return Err("softmax nonfinite".into())}max_abs=max_abs.max((*a as f64-b).abs())}if max_abs>1e-6{return Err(format!("softmax F64 max abs {max_abs}"))}reset32(&d,&dsoft,sentinel.to_bits())?;let mut start=0;for &rows in &p.partitions{soft(start,rows)?;start+=rows}check(&read(&d,&dsoft)?,&baseline,"softmax partitions")?;reset32(&d,&dsoft,sentinel.to_bits())?;for r in 0..p.rows{soft(r,1)?}check(&read(&d,&dsoft)?,&baseline,"softmax singleton")?;reset32(&d,&dsoft,sentinel.to_bits())?;graph_owner::completed_graph_launch(&d,||soft(0,p.rows))?;check(&read(&d,&dsoft)?,&baseline,"softmax graph")?;
 let widened=read(&d,&dw)?;if widened[..guard].iter().chain(&widened[guard+bf16.len()..]).any(|x|x.to_bits()!=sentinel.to_bits())||baseline[..guard].iter().chain(&baseline[guard+scores.len()..]).any(|x|x.to_bits()!=sentinel.to_bits()){return Err("conversion/softmax guard overwritten".into())}
 for (before,after)in [(&abs,read(&d,&da)?),(&q,read(&d,&dq)?),(&padded,read(&d,&ds)?),(&scores,read(&d,&dscore)?)]{check(before,&after,"readonly F32")?}if d.dtoh_sync_copy(&dc).map_err(|e|e.to_string())?!=c||if let Some(dk)=&dk{d.dtoh_sync_copy(dk).map_err(|e|e.to_string())?!=k}else{!k.is_empty()}||d.dtoh_sync_copy(&di).map_err(|e|e.to_string())?!=selected||d.dtoh_sync_copy(&dp).map_err(|e|e.to_string())?!=positions||d.dtoh_sync_copy(&db).map_err(|e|e.to_string())?!=bf16{return Err("readonly compact/integer/BF16 input mutated".into())}
 fs::create_dir_all(root).map_err(|e|e.to_string())?;for i in 0..3{fs::write(root.join(format!("gather-{i}.f32")),serial(&read(&d,&outputs[i])?[guard..guard+active[i]])).map_err(|e|e.to_string())?}fs::write(root.join("softmax.f32"),serial(&baseline[guard..guard+scores.len()])).map_err(|e|e.to_string())?;fs::write(root.join("scores.f32"),serial(&scores)).map_err(|e|e.to_string())?;
 fs::write(root.join("widen.f32"),serial(&widened[guard..guard+bf16.len()])).map_err(|e|e.to_string())?;let sc=d.dtoh_sync_copy(&dout).map_err(|e|e.to_string())?;fs::write(root.join("scatter.bf16"),sc[guard..guard+count].iter().flat_map(|x|x.to_le_bytes()).collect::<Vec<_>>()).map_err(|e|e.to_string())?;
 let report=json!({"passed":true,"gpu_uuid":actual,"plan_sha256":hash(&plan_raw),"kernel_identity":ops.identity,"rows":p.rows,"heads":p.heads,"ccd":p.ccd,"rope":p.rope,"codec":p.codec,"gather_full_partition_singleton_graph_exact":true,"gather_error_unwind_recovery_exact":true,"gather_guards_exact":true,"actual_bf16_widen_exact":true,"scatter_full_partition_singleton_graph_exact":true,"scatter_guards_exact":true,"softmax_full_partition_singleton_graph_exact":true,"softmax_f64_max_abs":max_abs,"all_readonly_inputs_exact":true,"scope":"Actual/cropped retained operator operands only; no installed serving or throughput qualification"});fs::write(root.join("REPORT.json"),serde_json::to_vec_pretty(&report).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;println!("{report}");Ok(())
}
fn main(){let args:Vec<_>=std::env::args().collect();if std::env::var("KRASIS_DEV_SCRIPT").as_deref()!=Ok("1")||args.len()!=3{eprintln!("Use ./dev stable-ops-probe <plan> <fresh-output>");std::process::exit(2)}if let Err(e)=run(Path::new(&args[1]),Path::new(&args[2])){eprintln!("{e}");std::process::exit(1)}}
